# Exact normalized title, full description, or numeric price keys.
def exact_normalized(r):
    import re
    import hashlib
    import unicodedata
    from decimal import Decimal, InvalidOperation

    def norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
        return " ".join(re.findall(r"[a-z0-9]+", s.lower()))

    def digest(prefix, value):
        return prefix + hashlib.blake2s(value.encode(), digest_size=10).hexdigest()

    def norm_price(s):
        s = re.sub(r"[^\d,.\-+eE]", "", str(s or "").replace(" ", ""))
        if not s:
            return ""
        if "," in s and "." in s:
            s = s.replace(",", "") if s.rfind(".") > s.rfind(",") else s.replace(".", "").replace(",", ".")
        elif "," in s:
            tail = s.rsplit(",", 1)[-1]
            s = s.replace(",", ".") if len(tail) <= 2 else s.replace(",", "")
        try:
            d = Decimal(s)
            return format(d.normalize(), "f")
        except InvalidOperation:
            return ""

    title = norm(r.get("title", ""))
    desc = norm(r.get("description", ""))
    price = norm_price(r.get("price", ""))
    keys = []
    if title:
        keys.append(digest("xt:", title))
    if len(desc) >= 20:
        keys.append(digest("xd:", desc))
    if price:
        keys.append("xp:" + price)
    return keys


# Model-code and compound number/unit keys tolerant of punctuation and token joining.
def identifier_aliases(r):
    import re
    import hashlib
    import unicodedata

    text = " ".join(str(r.get(a, "") or "") for a in ("title", "brand", "description"))
    text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode().lower()
    raw = re.findall(r"[a-z]+|\d+", text)
    candidates = set()

    for match in re.finditer(r"[a-z0-9]+(?:[\-./_+][a-z0-9]+)+|[a-z]*\d+[a-z0-9]*", text):
        value = re.sub(r"[^a-z0-9]", "", match.group())
        if len(value) >= 4:
            candidates.add(value)

    for n in range(2, 5):
        for i in range(len(raw) - n + 1):
            parts = raw[i:i + n]
            value = "".join(parts)
            if len(value) >= 4 and any(x.isdigit() for x in value) and any(x.isalpha() for x in value):
                candidates.add(value)

    expanded = set(candidates)
    for value in candidates:
        m = re.fullmatch(r"([a-z]+\d+)[a-z]{1,2}", value)
        if m and len(m.group(1)) >= 4:
            expanded.add(m.group(1))
        m = re.fullmatch(r"([a-z]{2,}\d+)(?:[a-z]\d+)+", value)
        if m:
            expanded.add(m.group(1))

    ranked = sorted(
        expanded,
        key=lambda x: (sum(c.isdigit() for c in x), len(x), x),
        reverse=True,
    )[:18]
    return [
        "id:" + hashlib.blake2s(x.encode(), digest_size=8).hexdigest()
        for x in ranked
    ]


# Long token, phonetic token, and character-LSH keys for reordered or lightly edited titles.
def lexical_character_signatures(r):
    import re
    import hashlib
    import unicodedata

    title = unicodedata.normalize("NFKD", str(r.get("title", "") or "")).encode("ascii", "ignore").decode().lower()
    tokens = re.findall(r"[a-z0-9]+", title)
    informative = sorted(
        set(t for t in tokens if len(t) >= 6 or (len(t) >= 4 and any(c.isdigit() for c in t))),
        key=lambda x: (len(x), x),
        reverse=True,
    )

    def soundex(word):
        first = word[0]
        groups = {
            **dict.fromkeys("bfpv", "1"),
            **dict.fromkeys("cgjkqsxz", "2"),
            **dict.fromkeys("dt", "3"),
            "l": "4",
            **dict.fromkeys("mn", "5"),
            "r": "6",
        }
        out, previous = [], groups.get(first, "")
        for c in word[1:]:
            code = groups.get(c, "")
            if code and code != previous:
                out.append(code)
            previous = code
        return (first + "".join(out) + "000")[:4]

    keys = []
    for token in informative[:8]:
        keys.append("tk:" + hashlib.blake2s(token.encode(), digest_size=7).hexdigest())
    for token in [t for t in informative if t.isalpha()][:5]:
        keys.append("ph:" + soundex(token))

    compact = "".join(tokens)
    if len(compact) >= 8:
        grams = {compact[i:i + 3] for i in range(len(compact) - 2)}
        vector = [0] * 64
        for gram in grams:
            h = int.from_bytes(hashlib.blake2b(gram.encode(), digest_size=8).digest(), "big")
            for bit in range(64):
                vector[bit] += 1 if (h >> bit) & 1 else -1
        signature = sum((1 << bit) for bit, value in enumerate(vector) if value >= 0)
        for band in range(4):
            keys.append("ls%d:%04x" % (band, (signature >> (band * 16)) & 0xffff))
    return list(dict.fromkeys(keys))


# Coarse numeric-title fallback using independent modular leading-character partitions.
def coarse_missing_tolerant(r):
    import re
    import unicodedata

    title = unicodedata.normalize("NFKD", str(r.get("title", "") or "")).encode("ascii", "ignore").decode().lower()
    letters = re.findall(r"[a-z]", title)
    if not letters or not re.search(r"\d", title):
        return []
    lead = ord(letters[0]) - ord("a")
    digit_runs = re.findall(r"\d+", title)
    keys = [
        "cm3:" + str(lead % 3),
        "cm17:" + str(lead % 17),
    ]
    if digit_runs:
        longest = max(map(len, digit_runs))
        keys.append("cdl:" + str(min(longest, 6)))
    return keys


